#include "agentflow/agent_worker_remote_host.hpp"
#include "agentflow/agent_model_values.hpp"
#include "agentflow/xlang_sqlite.hpp"
// Real controller approvals and synthetic MCP peer effects; model/lease identities
// are controlled backend fixtures. Actual-child IPC is a separate contract.
void durable_remote_host_contract(const std::vector<std::string>& imports){
    for(const std::string mode:{"approved","denied","policy","cancel","unrecorded","retired"}){
        Directory directory;const auto root=directory.path/"workspace";std::filesystem::create_directory(root);WorkspaceTools workspace(root.string());WorkspaceToolSet members(workspace.identity(),7,{{workspace.identity(),workspace.root_path()}});RepositoryInstructionContext guidance(workspace,workspace.repository_instructions("."));guidance.prepare();const auto database=(directory.path/"worker.sqlite").string();
        {
            PersistenceService store(database,imports);const std::string provider=R"({"wire":"chat-completions","model_id":"remote-worker-fixture"})";store.create_session("session","Durable native remote host").get();store.start_prompt_run("run","session",R"({"content":"Actual approved peer effect with synthetic model admission"})",RootBudgetSpec{"native.direct-agent",1,workspace.identity(),provider,0,0,8,600000}).get();store.transition("run",RunState::queued,RunState::running).get();store.append_event("run","agent.workspace_membership",Json{{"workspace_id",workspace.identity()},{"revision",7},{"primary_folder_id",workspace.identity()},{"folders",Json::array({{{"folder_id",workspace.identity()},{"root",workspace.root_path()}}})}}.dump()).get();
            const auto deadline=std::chrono::steady_clock::now()+20s;const auto lease=store.admit_agent_worker({"remote-host-generation","run","run",workspace.identity(),7,12345,"134000000000000000","synthetic-remote-worker-identity",provider}).get().spec;
            SyntheticMcpClient peer(directory.path/"peer-effect.txt");McpToolRegistry registry(peer,store,workspace,"durable-peer",1,deadline);const auto alias=registry.definitions().at(0).name;
            AgentRemoteToolInvocation call;call.run_id="run";call.attempt_id="remote-model";call.call_id="actual-remote";call.workspace_id=workspace.identity();call.workspace_revision=7;call.tool_name=alias;call.arguments_json=R"({"text":"once"})";
            ModelCompletion response{"","","tool_calls",R"({"total_tokens":17})",{{call.call_id,call.tool_name,call.arguments_json}},"[]"};store.reserve_agent_worker_model(lease,call.attempt_id,deadline).get();store.start_agent_worker_model(lease,call.attempt_id,deadline).get();AgentWorkerModelClaimSpec model{lease.generation,"run","run",call.attempt_id,context_digest("synthetic remote model window")};store.claim_agent_worker_model(model).get();store.record_agent_worker_model_response(model,encode_agent_model_completion(response),format_agent_model_assistant(response,"remote-worker-fixture",23,5)).get();store.finish_agent_worker_model(lease,call.attempt_id,deadline).get();
            AgentRemoteToolOwnerContext owner;owner.run_id="run";owner.primary_workspace=&workspace;owner.workspace_members=&members;owner.repository_context=&guidance;owner.offered_tool=[&](const std::string& name){return name==alias;};owner.mcp_registry=[&](const std::string& name){return name==alias?&registry:nullptr;};owner.a2a_registry=[](const std::string&)->A2aAgentToolRegistry*{return nullptr;};owner.deadline=deadline;if(mode=="policy")owner.permission_layers={{{alias,"*","deny"}}};AgentWorkerRemoteHost host(store,lease,owner,deadline);
            std::unique_ptr<XlangSqlite> fault;if(mode=="unrecorded"){fault=std::make_unique<XlangSqlite>(database,imports);fault->execute("CREATE TRIGGER fixture_remote_result_abort BEFORE UPDATE ON information WHEN OLD.category='native-agent-worker-remote-claims' AND json_extract(NEW.payload,'$.state')='returned' BEGIN SELECT RAISE(ABORT,'fixture_remote_result_abort'); END");}
            if(mode=="policy"){const auto result=host.invoke(call);need(!result.success&&Json::parse(result.output_json).at("error").at("code")=="agent_permission_denied"&&store.operations("run").get().empty(),"Inherited policy must reject before a remote proposal");}
            else{Task task(host,call);const auto proposal=pending(store,0);need(store.agent_worker_remote_claim("run",call.attempt_id,call.call_id).get().state=="executing"&&peer.sends==0,"Remote call must be durable while actual controller approval is pending");if(mode=="cancel")task.stop.request_stop();else{if(mode=="retired")store.retire_agent_worker(lease.generation,"worker_exit").get();store.decide_operation(proposal.id,mode=="denied"?OperationDecision::deny:OperationDecision::allow,"remote-controller").get();}
                if(mode=="cancel")rejects<ToolCancelled>([&]{task.result.get();});else if(mode=="retired")rejects<Conflict>([&]{task.result.get();});else if(mode=="unrecorded")rejects<AgentWorkerRemoteOutcomeUnrecorded>([&]{task.result.get();});else need(task.result.get().success==(mode=="approved"),"Actual remote result must reflect the controller decision");
            }
            const bool effected=mode=="approved"||mode=="unrecorded";need(peer.sends==(effected?1:0)&&std::filesystem::exists(peer.effect)==effected,"Only approved live authority may send the peer effect exactly once");const auto saved=store.agent_worker_remote_claim("run",call.attempt_id,call.call_id).get();if(effected){need(read(peer.effect)=="once"&&saved.operation_ids.size()==1&&store.operation(saved.operation_ids[0]).get().state==OperationState::succeeded,"Actual peer acknowledgement must retain its native effect binding");if(mode=="approved")need(saved.success&&saved.actual_output_json==store.operation(saved.operation_ids[0]).get().result_json,"Remote delivery must retain the exact native acknowledgement");}if(mode=="unrecorded"){need(saved.state=="executing"&&saved.actual_output_json.empty(),"Unrecorded remote result must not invent an acknowledgement");fault->execute("DROP TRIGGER fixture_remote_result_abort");}
            AgentWorkerRemoteHost rebuilt(store,lease,owner,deadline);rejects<Conflict>([&]{rebuilt.invoke(call);});if(mode!="retired")store.retire_agent_worker(lease.generation,"worker_exit").get();store.transition("run",RunState::running,RunState::cancelled).get();
        }
        {PersistenceService reopened(database,imports);const auto saved=reopened.agent_worker_remote_claim("run","remote-model","actual-remote").get();need(saved.state==(mode=="unrecorded"?"uncertain":"returned"),"Remote SQLite reopen must retain exact acknowledged and uncertain ownership");}
        std::cout<<"Durable native remote host "<<mode<<" verified actual approval, peer-effect count, receipt and reconstruction replay rejection."<<std::endl;
    }
}
